Below is a self‑contained Go program that implements a tiny in‑memory task manager with a RESTful HTTP API.  
It uses only the Go standard library, so you can run it with `go run main.go` (or build it with `go build`).  

```go
// main.go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

// Task represents a single to‑do item.
type Task struct {
	ID   int64  `json:"id"`   // unique identifier
	Name string `json:"name"` // short description
	Done bool   `json:"done"` // completion flag
}

// store holds all {{p:entity}} in memory and protects them with a mutex.
type store struct {
	mu    sync.RWMutex
	next  int64
	items map[int64]*Task
}

// newStore creates an empty store.
func newStore() *store {
	return &store{
		next:  1,
		items: make(map[int64]*Task),
	}
}

// List returns a slice with all {{p:entity}}.
func (s *store) List() []*Task {
	s.mu.RLock()
	defer s.mu.RUnlock()
	list := make([]*Task, 0, len(s.items))
	for _, t := range s.items {
		list = append(list, t)
	}
	return list
}

// Get returns a task by id, or nil if it does not exist.
func (s *store) Get(id int64) *Task {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.items[id]
}

// Create adds a new task and returns it (with a generated ID).
func (s *store) Create(name string) *Task {
	s.mu.Lock()
	defer s.mu.Unlock()
	t := &Task{
		ID:   s.next,
		Name: name,
		Done: false,
	}
	s.items[s.next] = t
	s.next++
	return t
}

// Delete removes a task. Returns true if the task existed.
func (s *store) Delete(id int64) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.items[id]; !ok {
		return false
	}
	delete(s.items, id)
	return true
}

// ----------- HTTP handlers ------------

func listHandler(st *store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		{{p:entity}} := st.List()
		respondJSON(w, http.StatusOK, {{p:entity}})
	}
}

func getHandler(st *store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id, err := parseID(r.URL.Path)
		if err != nil {
			respondError(w, http.StatusBadRequest, "invalid task id")
			return
		}
		task := st.Get(id)
		if task == nil {
			respondError(w, http.StatusNotFound, "task not found")
			return
		}
		respondJSON(w, http.StatusOK, task)
	}
}

func createHandler(st *store) http.HandlerFunc {
	type payload struct {
		Name string `json:"name"`
	}
	return func(w http.ResponseWriter, r *http.Request) {
		var p payload
		if err := json.NewDecoder(r.Body).Decode(&p); err != nil {
			respondError(w, http.StatusBadRequest, "invalid JSON payload")
			return
		}
		if strings.TrimSpace(p.Name) == "" {
			respondError(w, http.StatusBadRequest, "name cannot be empty")
			return
		}
		task := st.Create(p.Name)
		respondJSON(w, http.StatusCreated, task)
	}
}

func deleteHandler(st *store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id, err := parseID(r.URL.Path)
		if err != nil {
			respondError(w, http.StatusBadRequest, "invalid task id")
			return
		}
		if ok := st.Delete(id); !ok {
			respondError(w, http.StatusNotFound, "task not found")
			return
		}
		w.WriteHeader(http.StatusNoContent) // 204 No Content
	}
}

// ----------- Helper utilities ------------

func parseID(path string) (int64, error) {
	// Expected path: /{{p:entity}}/{id}
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) != 2 {
		return 0, http.ErrNotSupported
	}
	return strconv.ParseInt(parts[1], 10, 64)
}

func respondJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func respondError(w http.ResponseWriter, status int, msg string) {
	respondJSON(w, status, map[string]string{"error": msg})
}

// ----------- Main entry point ------------

func main() {
	st := newStore()

	mux := http.NewServeMux()
	mux.HandleFunc("/{{p:entity}}", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			listHandler(st)(w, r)
		case http.MethodPost:
			createHandler(st)(w, r)
		default:
			respondError(w, http.StatusMethodNotAllowed, "method not allowed")
		}
	})
	// Routes that contain an ID: /{{p:entity}}/{id}
	mux.HandleFunc("/{{p:entity}}/", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			getHandler(st)(w, r)
		case http.MethodDelete:
			deleteHandler(st)(w, r)
		default:
			respondError(w, http.StatusMethodNotAllowed, "method not allowed")
		}
	})

	addr := ":8080"
	log.Printf("Task API listening on http://localhost%s/", addr)
	if err := http.ListenAndServe(addr, mux); err != nil {
		log.Fatalf("Server error: %v", err)
	}
}
```

### How it works

| HTTP method | URL pattern      | Description                         |
|-------------|------------------|-------------------------------------|
| `GET`       | `/{{p:entity}}`         | Returns a JSON array of all {{p:entity}}. |
| `GET`       | `/{{p:entity}}/{id}`    | Returns a single task ({{int:323:485}} if missing). |
| `POST`      | `/{{p:entity}}`         | Creates a task. Body: `{ "name": "my task" }`. Returns the created task with its generated `id`. |
| `DELETE`    | `/{{p:entity}}/{id}`    | Deletes a task ({{int:163:245}} on success, {{int:323:485}} if not found). |

All data lives only in RAM (`store` struct). When the program stops, the {{p:entity}} disappear – perfect for quick prototyping, demos, or unit tests.

### Running the example

```bash
go run main.go
```

The server starts on **localhost:8080**. You can test it with `curl`:

```bash
# Create a task
curl -X POST -d '{"name":"Buy milk"}' -H "Content-Type: application/json" http://localhost:8080/{{p:entity}}

# List {{p:entity}}
curl http://localhost:8080/{{p:entity}}

# Get a task (replace 1 with the actual id)
curl http://localhost:8080/{{p:entity}}/1

# Delete a task
curl -X DELETE http://localhost:8080/{{p:entity}}/1
```

Feel free to expand the `Task` struct, add more fields (e.g., `DueDate`, `Priority`), or persist data to a file or database when you need durability.

Here is a companion **`main_test.go`** file that exercises the full REST API you just built.  
It uses only the standard library (`net/http/httptest`, `encoding/json`, `testing`) and therefore can be run with:

```bash
go test -v
```

```go
// main_test.go
package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strconv"
	"testing"
)

// helper to create a test server with the same routes as main()
func newTestServer() *httptest.Server {
	st := newStore()

	mux := http.NewServeMux()
	mux.HandleFunc("/{{p:entity}}", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			listHandler(st)(w, r)
		case http.MethodPost:
			createHandler(st)(w, r)
		default:
			respondError(w, http.StatusMethodNotAllowed, "method not allowed")
		}
	})
	mux.HandleFunc("/{{p:entity}}/", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			getHandler(st)(w, r)
		case http.MethodDelete:
			deleteHandler(st)(w, r)
		default:
			respondError(w, http.StatusMethodNotAllowed, "method not allowed")
		}
	})

	return httptest.NewServer(mux)
}

// -------------------------------------------------------------------
// Test suite
// -------------------------------------------------------------------

// TestCreateGetDelete runs the full lifecycle:
//   * POST /{{p:entity}}   → creates a task
//   * GET  /{{p:entity}}/:id → retrieves it
//   * DELETE /{{p:entity}}/:id → removes it
//   * GET  /{{p:entity}}/:id → confirms 404
func TestCreateGetDelete(t *testing.T) {
	ts := newTestServer()
	defer ts.Close()

	// ---- 1️⃣ Create -------------------------------------------------
	createPayload := map[string]string{"name": "Write unit tests"}
	body, _ := json.Marshal(createPayload)

	resp, err := http.Post(ts.URL+"/{{p:entity}}", "application/json", bytes.NewReader(body))
	if err != nil {
		t.Fatalf("POST request failed: %v", err)
	}
	if resp.StatusCode != http.StatusCreated {
		t.Fatalf("expected status 201 Created, got %d", resp.StatusCode)
	}
	var created Task
	if err := json.NewDecoder(resp.Body).Decode(&created); err != nil {
		t.Fatalf("failed to decode create response: %v", err)
	}
	resp.Body.Close()

	if created.ID == 0 {
		t.Fatalf("expected non‑zero task ID")
	}
	if created.Name != "Write unit tests" {
		t.Fatalf("expected name %q, got %q", "Write unit tests", created.Name)
	}
	if created.Done {
		t.Fatalf("new task should not be marked done")
	}

	// ---- 2️⃣ Get ----------------------------------------------------
	getResp, err := http.Get(ts.URL + "/{{p:entity}}/" + strconv.FormatInt(created.ID, 10))
	if err != nil {
		t.Fatalf("GET request failed: %v", err)
	}
	if getResp.StatusCode != http.StatusOK {
		t.Fatalf("expected status 200 OK for GET, got %d", getResp.StatusCode)
	}
	var fetched Task
	if err := json.NewDecoder(getResp.Body).Decode(&fetched); err != nil {
		t.Fatalf("failed to decode GET response: %v", err)
	}
	getResp.Body.Close()

	if fetched != created {
		t.Fatalf("fetched task does not match created task.\nCreated: %+v\nFetched: %+v", created, fetched)
	}

	// ---- 3️⃣ Delete -------------------------------------------------
	req, err := http.NewRequest(http.MethodDelete, ts.URL+"/{{p:entity}}/"+strconv.FormatInt(created.ID, 10), nil)
	if err != nil {
		t.Fatalf("failed to build DELETE request: %v", err)
	}
	delResp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("DELETE request failed: %v", err)
	}
	if delResp.StatusCode != http.StatusNoContent {
		t.Fatalf("expected status 204 No Content for DELETE, got %d", delResp.StatusCode)
	}
	delResp.Body.Close()

	// ---- 4️⃣ Verify deletion ----------------------------------------
	getAfterDel, err := http.Get(ts.URL + "/{{p:entity}}/" + strconv.FormatInt(created.ID, 10))
	if err != nil {
		t.Fatalf("GET after DELETE failed: %v", err)
	}
	if getAfterDel.StatusCode != http.StatusNotFound {
		t.Fatalf("expected status 404 Not Found after delete, got %d", getAfterDel.StatusCode)
	}
	getAfterDel.Body.Close()
}

// TestListEmptyAndAfterCreates verifies that the list endpoint
// returns an empty slice initially and then reflects added {{p:entity}}.
func TestListEmptyAndAfterCreates(t *testing.T) {
	ts := newTestServer()
	defer ts.Close()

	// 1️⃣ List should be empty initially
	resp, err := http.Get(ts.URL + "/{{p:entity}}")
	if err != nil {
		t.Fatalf("initial GET /{{p:entity}} failed: %v", err)
	}
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("expected 200 OK for initial list, got %d", resp.StatusCode)
	}
	var list []Task
	if err := json.NewDecoder(resp.Body).Decode(&list); err != nil {
		t.Fatalf("decoding initial list failed: %v", err)
	}
	resp.Body.Close()
	if len(list) != 0 {
		t.Fatalf("expected empty task list, got %d items", len(list))
	}

	// 2️⃣ Create a few {{p:entity}}
	names := []string{"Task A", "Task B", "Task C"}
	createdIDs := make([]int64, 0, len(names))
	for _, n := range names {
		pl := map[string]string{"name": n}
		b, _ := json.Marshal(pl)
		r, err := http.Post(ts.URL+"/{{p:entity}}", "application/json", bytes.NewReader(b))
		if err != nil {
			t.Fatalf("POST %q failed: %v", n, err)
		}
		if r.StatusCode != http.StatusCreated {
			t.Fatalf("expected 201 for %q, got %d", n, r.StatusCode)
		}
		var tsk Task
		if err := json.NewDecoder(r.Body).Decode(&tsk); err != nil {
			t.Fatalf("decode created %q: %v", n, err)
		}
		r.Body.Close()
		createdIDs = append(createdIDs, tsk.ID)
	}

	// 3️⃣ List should now contain exactly the created {{p:entity}} (order is not guaranteed)
	resp2, err := http.Get(ts.URL + "/{{p:entity}}")
	if err != nil {
		t.Fatalf("second GET /{{p:entity}} failed: %v", err)
	}
	if resp2.StatusCode != http.StatusOK {
		t.Fatalf("expected 200 OK for second list, got %d", resp2.StatusCode)
	}
	var after []Task
	if err := json.NewDecoder(resp2.Body).Decode(&after); err != nil {
		t.Fatalf("decode second list: %v", err)
	}
	resp2.Body.Close()

	if len(after) != len(names) {
		t.Fatalf("expected %d {{p:entity}} after creation, got %d", len(names), len(after))
	}

	// Verify each created ID appears exactly once
	seen := make(map[int64]bool)
	for _, tsk := range after {
		if seen[tsk.ID] {
			t.Fatalf("duplicate task ID %d in list", tsk.ID)
		}
		seen[tsk.ID] = true
	}
	for _, id := range createdIDs {
		if !seen[id] {
			t.Fatalf("created task ID %d not present in list", id)
		}
	}
}

// TestInvalidPayload ensures the API returns proper errors for bad input.
func TestInvalidPayload(t *testing.T) {
	ts := newTestServer()
	defer ts.Close()

	// Empty body
	resp, err := http.Post(ts.URL+"/{{p:entity}}", "application/json", bytes.NewReader([]byte("{}")))
	if err != nil {
		t.Fatalf("POST empty payload failed: %v", err)
	}
	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("expected 400 Bad Request for empty name, got %d", resp.StatusCode)
	}
	resp.Body.Close()

	// Invalid JSON
	resp2, err := http.Post(ts.URL+"/{{p:entity}}", "application/json", bytes.NewReader([]byte("{invalid")))
	if err != nil {
		t.Fatalf("POST malformed JSON failed: %v", err)
	}
	if resp2.StatusCode != http.StatusBadRequest {
		t.Fatalf("expected 400 for malformed JSON, got %d", resp2.StatusCode)
	}
	resp2.Body.Close()
}
```

### What the tests cover

| Test | What it verifies |
|------|------------------|
| **`TestCreateGetDelete`** | Full lifecycle – creation (`POST`), retrieval (`GET`), deletion (`DELETE`), and that the task is gone afterwards (`GET` → {{int:323:485}}). |
| **`TestListEmptyAndAfterCreates`** | The list endpoint returns an empty slice when no {{p:entity}} exist, then correctly reflects newly created {{p:entity}}. |
| **`TestInvalidPayload`** | The server responds with `{{int:320:480}} Bad Request` for an empty `name` field and for malformed JSON. |

### Running the suite

1. Save the original program as `main.go` and the tests as `main_test.go` in the same directory.  
2. Execute:

```bash
go test -v
```

You should see output similar to:

```
=== RUN   TestCreateGetDelete
--- PASS: TestCreateGetDelete (0.00s)
=== RUN   TestListEmptyAndAfterCreates
--- PASS: TestListEmptyAndAfterCreates (0.00s)
=== RUN   TestInvalidPayload
--- PASS: TestInvalidPayload (0.00s)
PASS
ok  	<module-path>	0.xxxs
```

These tests give you confidence that the in‑memory task API behaves as expected and can serve as a foundation for further enhancements (e.g., updating {{p:entity}}, pagination, persistence).
